#include "carry_op0_origin.hpp"
#include <cstdio>
namespace p=mgscoop::carry_op0_origin;namespace h=mgscoop::carry_owned_handshake;
unsigned passed=0,failed=0;void Check(bool value,const char* name){++passed;if(!value){++failed;std::printf("FAIL %s\n",name);}}
int main(){constexpr std::uintptr_t image=0x140000000,record=0x20000;h::MessagePrefix packet{mgscoop::carry_request_payload::kHandshakeHash,0,0,0,record};
 Check(p::NaturalSource(image,image+p::senderReturn,image+p::serviceRva,1,packet,record),"exact actual native source tuple");
 Check(!p::NaturalSource(image,image+p::senderReturn-1,image+p::serviceRva,1,packet,record),"nearby return address refuses");
 Check(!p::NaturalSource(image,image+p::op1Return,image+p::serviceRva,1,packet,record),"reciprocal op1 is distinct");
 Check(!p::NaturalSource(image,image+p::senderReturn,image+p::serviceRva+8,1,packet,record),"different service root refuses");
 Check(!p::NaturalSource(image,image+p::senderReturn,image+p::serviceRva,0,packet,record),"local target0 cannot be inferred");
 auto changed=packet;changed.carrier=1;Check(!p::NaturalSource(image,image+p::senderReturn,image+p::serviceRva,1,changed,record),"different source body refuses");
 changed=packet;changed.reserved=1;Check(p::NaturalSource(image,image+p::senderReturn,image+p::serviceRva,1,changed,record),"unused native stack padding does not reject source");
 changed=packet;changed.operation=1;Check(!p::NaturalSource(image,image+p::senderReturn,image+p::serviceRva,1,changed,record),"non-op0 operation refuses");
 changed=packet;changed.hash^=1;Check(!p::NaturalSource(image,image+p::senderReturn,image+p::serviceRva,1,changed,record),"other message hash refuses");
 changed=packet;changed.carrierRecord+=16;Check(!p::NaturalSource(image,image+p::senderReturn,image+p::serviceRva,1,changed,record),"different record lease refuses");
 unsigned char tags[0x90]{};tags[0x80]=0;tags[0x81]=0x22;tags[0x85]=1;std::uint8_t actual=0xff,offline=0;
 auto reader=[&](std::uintptr_t at,void* out,std::size_t n){if(at<record||at-record>sizeof(tags)||n>sizeof(tags)-(at-record))return false;std::memcpy(out,tags+(at-record),n);return true;};
 Check(p::ReadCarrierTag(reader,record,actual,offline)&&actual==0&&offline==1,"actual byte carrier tag ignores progress neighbor81");
 tags[0x80]=1;Check(p::ReadCarrierTag(reader,record,actual,offline)&&actual==1,"different actual byte remains observable");
 Check(!p::ReadCarrierTag(reader,UINTPTR_MAX-0x10,actual,offline),"carrier tag arithmetic refuses wrap");
 unsigned char before[0x6c0]{},after[0x6c0]{},matrix[64]{};for(unsigned n=0;n<64;++n)matrix[n]=static_cast<unsigned char>(n*7+1);
 std::memcpy(after+0x1d0,matrix,64);Check(p::CopyOnly(before,after,matrix,0),"native copy-out changes only matrix");
 Check(!p::CopyOnly(before,after,matrix,1),"nonzero native result never seals");
 after[0x20]^=1;Check(!p::CopyOnly(before,after,matrix,0),"early unrelated record mutation refuses");after[0x20]^=1;
 after[0x6bf]^=1;Check(!p::CopyOnly(before,after,matrix,0),"late unrelated record mutation refuses");after[0x6bf]^=1;
 after[0x20f]^=1;Check(!p::CopyOnly(before,after,matrix,0),"matrix end byte must match actual model");after[0x20f]^=1;
 Check(!p::CopyOnly(nullptr,after,matrix,0),"missing prior state refuses");
 using D=p::Domain;using R=p::Route;
 Check(p::DispatchRoute(D::owned,false,false,false,0)==R::stock,"cold owned writer preserves native dispatch");
 Check(p::DispatchRoute(D::owned,true,true,true,1)==R::refuse,"Carry-held selected1 dispatch requires separate op1 receipt");
 Check(p::DispatchRoute(D::shared,true,true,true,1)==R::origin,"exact confirmed natural source requires real shared ticket");
 Check(p::DispatchRoute(D::none,true,true,true,1)==R::refuse,"confirmed source without actual domain refuses");
 Check(p::DispatchRoute(D::shared,true,false,true,1)==R::refuse,"prepared or partial submission cannot dispatch");
 Check(p::DispatchRoute(D::shared,true,true,false,1)==R::refuse,"foreign held recipient1 sender refuses");
 Check(p::DispatchRoute(D::shared,true,true,false,0)==R::refuse,"foreign held carrier0 sender refuses");
 Check(p::DispatchRoute(D::shared,true,true,false,0x6400)==R::stock,"unrelated actor dispatch retains actual shared exclusion");
 Check(p::DispatchRoute(D::shared,false,false,false,1)==R::stock,"Sleep-only shared stock dispatch preserves behavior");
 Check(p::RecipientRoute(D::shared,true,true,1)==R::origin,"exact paired source reaches recipient under its own shared ticket");
 Check(p::RecipientRoute(D::shared,true,false,1)==R::refuse,"absent provenance cannot forward held recipient");
 Check(p::RecipientRoute(D::shared,true,true,0)==R::refuse,"origin cannot target held carrier handler");
 Check(p::RecipientRoute(D::owned,true,true,1)==R::refuse,"owned projection cannot replace shared receipt");
 Check(p::RecipientRoute(D::none,true,true,1)==R::refuse,"untracked context cannot authorize held handler");
 Check(p::RecipientRoute(D::shared,false,false,1)==R::stock,"cold recipient stock route retains domain");
 p::Intent pending{};Check(!p::Current(pending,1,2,3,4,100),"empty intent is no authority");
 Check(p::Reserve(pending,11,12,100,13,14,15,0xff),"post-native mod seal reservation");
 Check(!p::Reserve(pending,11,13,101,13,14,15,0),"duplicate native handshake cannot resubmit");
 Check(p::Current(pending,11,13,14,15,850),"bounded current same cycle at deadline");
 Check(!p::Current(pending,11,13,14,15,851),"expired handshake refuses deferred delivery");
 Check(!p::Current(pending,11,13,14,15,99),"clock reversal refuses");
 Check(!p::Current(pending,12,13,14,15,101),"different submission nonce refuses");
 Check(!p::Current(pending,11,12,14,15,101),"different carry lease refuses");
 Check(!p::Current(pending,11,13,13,15,101),"different generation refuses");
 Check(!p::Current(pending,11,13,14,14,101),"different scene refuses");
 Check(p::SameCycle(pending,11,13,14,15),"native retry preserves first accepted intent");
 Check(!p::SameCycle(pending,12,13,14,15),"native retry from other submission refuses");
 pending.queued=true;Check(p::SameCycle(pending,11,13,14,15),"queued retry never creates second request");Check(!p::Current(pending,11,13,14,15,101),"consumed queue intent cannot repeat");
 p::Intent invalid{};Check(!p::Reserve(invalid,0,12,100,13,14,15,0),"zero submission refuses");
 Check(!p::Reserve(invalid,11,0,100,13,14,15,0),"zero intent nonce refuses");
 Check(!p::Reserve(invalid,11,12,0,13,14,15,0),"zero timestamp refuses");
 Check(!p::Reserve(invalid,11,12,100,0,14,15,0),"zero carry serial refuses");
 std::printf("carry_op0_origin: %u checks, %u failures; pure authored fixtures only\n",passed,failed);return failed?1:0;
}
